B.a5B=new A.bO("sentadilla","Sentadilla sin peso","Piernas y gl\xfateo",B.aiW,"Pecho alto y talones pegados al suelo. Si te cuesta, baja hasta una silla y lev\xe1ntate.",null,B.dC)
